using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — knows about any type.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1️⃣  GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>  → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 38), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2️⃣  TryGetTypeInfo<T>() — probes without throwing
if (webOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
{
    Console.WriteLine($"TryGetTypeInfo<Person> → found ({found!.Type.Name})");
}

// Now try a source-gen context that only knows about Person — Widget is unknown.
var strictOptions = new JsonSerializerOptions();
strictOptions.TypeInfoResolverChain.Add(PersonOnlyContext.Default);

if (strictOptions.TryGetTypeInfo<Widget>(out JsonTypeInfo<Widget>? widgetInfo))
{
    Console.WriteLine($"TryGetTypeInfo<Widget> → found ({widgetInfo!.Type.Name})");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Widget> → not available (no exception thrown)");
}

// --- types ---------------------------------------------------------------

public record Person(string Name, int Age);

public record Widget(int Id, string Label);

[JsonSerializable(typeof(Person))]
public partial class PersonOnlyContext : JsonSerializerContext;

