// TryGetTypeInfo<T>() — probe without throwing
var strictOptions = new JsonSerializerOptions();
strictOptions.TypeInfoResolverChain.Add(PersonOnlyContext.Default);

if (strictOptions.TryGetTypeInfo<Widget>(out _))
    /* have it */;
else
    /* don't have it — no exception */;
